//! Core patch 0003 (wirecompat) against the bulk images in `fixtures/wire/`:
//! the historical layouts of every shipped firmware since the V16 break,
//! generated by compiling each release's own `bulk_params.h`
//! (tools/wirecompat/gen_fixtures.sh, fixtures/wire/README.md).

use std::path::PathBuf;

use dspi_core::protocol::*;
use dspi_core::wirecompat::{self, *};
use dspi_ffi::fixture::{state_from_capture, state_from_capture_compat};

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn read(name: &str) -> Vec<u8> {
    std::fs::read(root().join("fixtures").join(name)).unwrap_or_else(|e| panic!("{name}: {e}"))
}

/// (wire version, firmware tag, REQ_GET_PLATFORM reply that firmware sends)
const SHIPPED: [(u8, &str, &[u8]); 6] = [
    (17, "v1.1.5-beta3", &[1, 1, 0x15, 9]),
    (21, "v1.1.5-beta4", &[1, 1, 0x15, 9]),
    (24, "v1.1.5-beta5", &[1, 1, 0x15, 9]),
    (26, "v1.1.5-beta6", &[1, 1, 0x15, 9]),
    (28, "v1.1.5", &[1, 1, 0x15, 9]),
    (30, "v1.1.6-beta3", &[1, 1, 0x16, 9, 1, 6, 3]),
];

/// Byte ranges of the V32 layout that a firmware of an older wire format did
/// not have: (V32 offset, length, first version that carries it). Restated
/// from the firmware's version log, independently of wirecompat.rs.
fn introduced() -> Vec<(usize, usize, u8)> {
    let ic = OFF_INPUT_CONFIG;
    let mut v = vec![
        (OFF_GLOBAL + 6, 2, 19),    // loudness_output_mask
        (OFF_CROSSFEED + 3, 1, 20), // crossfeed output_pair_mask
        (OFF_I2S + 8, 8, 21),       // clock_pin_mode_p1, bck_pin_slave, reserved[6]
        (OFF_LEVELLER + 16, 4, 18), // detector/apply masks, reserved2
        (ic + 8, 2, 21),            // spdif_rx_pin_ext[0..2]
        (ic + 10, 1, 28),           // spdif_rx_pin_ext[2] (S/PDIF 4)
        (ic + 11, 2, 21),           // spdif enable mask +1, i2s_clock_mode
        (ic + 13, 3, 24),           // ADAT input pin, enable +1, clock mode +1
        (OFF_ADAT, 8, 17),
        (OFF_PSYBASS, OFF_UPMIX - OFF_PSYBASS, 23),
        (OFF_UPMIX, 3, 25),
        (OFF_UPMIX + 3, 1, 26), // presence
        (OFF_UPMIX + 4, OFF_SUBHARM - OFF_UPMIX - 4, 25),
        (OFF_SUBHARM, 16, 29),
        (OFF_SUBHARM + 16, OFF_TUBE - OFF_SUBHARM - 16, 30),
        (OFF_TUBE, OFF_LIMITER - OFF_TUBE, 31),
        (OFF_LIMITER, BULK_PARAMS_SIZE - OFF_LIMITER, 32),
    ];
    // Linkwitz Transform Q in every EQ and crossover band's reserved bytes (V22)
    for k in 0..17 * 12 {
        v.push((OFF_EQ + k * 16 + 2, 2, 22));
    }
    for k in 0..17 * 4 {
        v.push((OFF_CROSSOVER + k * 16 + 2, 2, 22));
    }
    v
}

#[test]
fn fixtures_have_the_historical_sizes() {
    for (v, tag, _) in SHIPPED {
        for f in [format!("wire/bulk_v{v}.bin"), format!("wire/pattern_v{v}.bin")] {
            let d = read(&f);
            assert_eq!(d[0], v, "{f}");
            assert_eq!(Some(d.len()), bulk_size(v), "{f} ({tag})");
            assert_eq!(read_u16(&d, 6) as usize, d.len(), "{f}: payload_length");
            assert_eq!(wirecompat::image_length(&d[..16]), d.len());
        }
    }
}

fn read_u16(d: &[u8], off: usize) -> u16 {
    u16::from_le_bytes([d[off], d[off + 1]])
}

#[test]
fn older_patterns_map_onto_v32_byte_for_byte() {
    // Every byte of the pattern is distinctive, so a section or field placed
    // one byte off (the V18 and V28 shifts) cannot go unnoticed.
    let v32 = read("wire/pattern_v32.bin");
    assert_eq!(v32.len(), BULK_PARAMS_SIZE);
    for (v, tag, _) in SHIPPED {
        let old = read(&format!("wire/pattern_v{v}.bin"));
        let (img, r) = normalize(&old).unwrap();
        assert_eq!(r, WIRE_READ_OLDER);
        let mut want = v32.clone();
        want[..8].copy_from_slice(&old[..8]); // device version + payload_length
        for (off, len, since) in introduced() {
            if v < since {
                want[off..off + len].fill(0);
            }
        }
        if let Some(i) = (0..BULK_PARAMS_SIZE).find(|&i| img[i] != want[i]) {
            panic!("V{v} ({tag}): first difference at V32 offset {i}: got {} want {}", img[i], want[i]);
        }
    }
}

#[test]
fn older_captures_decode_to_the_v32_capture() {
    let platform = read("platform.bin");
    let v32 = state_from_capture(&platform, &read("bulk_v32.bin")).unwrap();
    assert_eq!((v32.wire_read, v32.wire_features), (WIRE_READ_EXACT, WIRE_FEATURES_ALL));
    for (v, tag, plat) in SHIPPED {
        let s = state_from_capture_compat(plat, &read(&format!("wire/bulk_v{v}.bin"))).unwrap();
        let ctx = format!("V{v} ({tag})");
        assert_eq!(s.format_version, v, "{ctx}");
        assert_eq!(s.compat, 2, "{ctx}: TOO_OLD, so every write stays refused");
        assert_eq!(s.wire_read, WIRE_READ_OLDER, "{ctx}");
        assert!(!s.bulk_valid, "{ctx}: no bulk write-back");
        assert_eq!(s.wire_features, wire_features(v), "{ctx}");
        assert_eq!((s.fw_major, s.fw_minor), (1, 1), "{ctx}");
        // Sections every shipped version carries decode to the same values.
        assert_eq!(s.num_channels, v32.num_channels, "{ctx}");
        assert_eq!(s.num_input_channels, v32.num_input_channels, "{ctx}");
        assert_eq!(s.num_output_channels, v32.num_output_channels, "{ctx}");
        assert_eq!(s.preamp_db, v32.preamp_db, "{ctx}");
        assert_eq!(s.input_preamp_db, v32.input_preamp_db, "{ctx}");
        assert_eq!(s.master_volume_db, v32.master_volume_db, "{ctx}");
        assert_eq!(s.user_volume_db, v32.user_volume_db, "{ctx}");
        assert_eq!(s.user_mute, v32.user_mute, "{ctx}");
        assert_eq!(s.channel_names, v32.channel_names, "{ctx}");
        assert_eq!(s.channel_delays, v32.channel_delays, "{ctx}");
        assert_eq!(s.matrix_routing, v32.matrix_routing, "{ctx}");
        assert_eq!(s.matrix_gain, v32.matrix_gain, "{ctx}");
        assert_eq!(s.output_enabled, v32.output_enabled, "{ctx}");
        assert_eq!(s.output_gain_db, v32.output_gain_db, "{ctx}");
        assert_eq!(s.output_delay_ms, v32.output_delay_ms, "{ctx}");
        assert_eq!(s.leveller_enabled, v32.leveller_enabled, "{ctx}");
        assert_eq!(s.leveller_amount, v32.leveller_amount, "{ctx}");
        assert_eq!(s.input_source, v32.input_source, "{ctx}");
        assert_eq!(s.dac_mute_pin, v32.dac_mute_pin, "{ctx}");
        assert_eq!(s.adat_out_enabled, v32.adat_out_enabled, "{ctx}");
        assert_eq!(s.lg_sound_sync_enabled, v32.lg_sound_sync_enabled, "{ctx}");
        for (ch, (a, b)) in s.filters.iter().zip(&v32.filters).enumerate() {
            for (band, (x, y)) in a.iter().zip(b).enumerate() {
                assert_eq!(
                    (x.filter_type, x.freq, x.q, x.gain),
                    (y.filter_type, y.freq, y.q, y.gain),
                    "{ctx} ch{ch} band{band}"
                );
            }
        }
        // Later sections: the device's own values where it has them, else absent.
        if v >= 23 {
            assert_eq!(s.psybass_cutoff_hz, v32.psybass_cutoff_hz, "{ctx}");
        } else {
            assert_eq!(s.psybass_cutoff_hz, 0.0, "{ctx}");
        }
        if v >= 24 {
            assert_eq!(s.adat_input_pin, v32.adat_input_pin, "{ctx}");
        }
        if v >= 30 {
            assert_eq!(s.subharm, v32.subharm, "{ctx}");
        }
        assert!(s.limiter_enabled.iter().all(|e| !e), "{ctx}: V32 limiter absent");
    }
}

#[test]
fn newer_image_shows_its_v32_prefix() {
    let platform = [1, 1, 0x17, 9, 1, 7, 1]; // a hypothetical 1.1.7-beta1
    let v32 = state_from_capture(&read("platform.bin"), &read("bulk_v32.bin")).unwrap();
    let d = read("wire/bulk_v33_mock.bin");
    assert_eq!((d[0], d.len()), (33, BULK_PARAMS_SIZE + 40));
    assert_eq!(wirecompat::image_length(&d[..16]), d.len());
    let s = state_from_capture_compat(&platform, &d).unwrap();
    assert_eq!((s.format_version, s.compat, s.wire_read), (33, 3, WIRE_READ_NEWER));
    assert!(!s.bulk_valid);
    assert_eq!(s.wire_features, WIRE_FEATURES_ALL);
    assert_eq!(s.master_volume_db, v32.master_volume_db);
    assert_eq!(s.channel_names, v32.channel_names);
    assert_eq!(s.filters, v32.filters);
    assert_eq!(s.limiter_threshold_db, v32.limiter_threshold_db);
    assert_eq!(s.tube, v32.tube);
}

#[test]
fn strict_decode_is_unchanged() {
    // decode_bulk (and so every V32 path) still refuses other versions.
    let mut st = dspi_core::state::DspState::default();
    assert_eq!(decode_bulk(&read("wire/bulk_v33_mock.bin"), &mut st), Err(BulkError::UnsupportedVersion(33)));
    assert_eq!(decode_bulk(&read("wire/bulk_v28.bin"), &mut st), Err(BulkError::TooShort));
}

#[test]
fn kotlin_mirror_matches_the_core() {
    // core-api WireCompat.kt mirrors the patch's constants by hand (the
    // contract generator reads only the unpatched submodule).
    let kt = std::fs::read_to_string(root().join("core-api/src/main/kotlin/se/bofr/dspi/core/WireCompat.kt")).unwrap();
    let val = |name: &str| -> i64 {
        let line =
            kt.lines().find(|l| l.contains(&format!("const val {name}:"))).unwrap_or_else(|| panic!("{name} missing"));
        let rhs = line.split('=').nth(1).unwrap().split("//").next().unwrap().trim();
        match rhs.split_once(" shl ") {
            Some((a, b)) => {
                a.trim().trim_end_matches('L').parse::<i64>().unwrap()
                    << b.split("//").next().unwrap().trim().parse::<i64>().unwrap()
            }
            None => rhs.trim_end_matches('L').parse().unwrap(),
        }
    };
    for (name, v) in [
        ("WIRE_READ_NONE", WIRE_READ_NONE as i64),
        ("WIRE_READ_EXACT", WIRE_READ_EXACT as i64),
        ("WIRE_READ_OLDER", WIRE_READ_OLDER as i64),
        ("WIRE_READ_NEWER", WIRE_READ_NEWER as i64),
        ("ADAT_OUT", WIRE_FEAT_ADAT_OUT as i64),
        ("LEVELLER_MASKS", WIRE_FEAT_LEVELLER_MASKS as i64),
        ("LOUDNESS_MASK", WIRE_FEAT_LOUDNESS_MASK as i64),
        ("CROSSFEED_MASK", WIRE_FEAT_CROSSFEED_MASK as i64),
        ("I2S_CLOCK_MODE", WIRE_FEAT_I2S_CLOCK_MODE as i64),
        ("LINKWITZ", WIRE_FEAT_LINKWITZ as i64),
        ("PSYBASS", WIRE_FEAT_PSYBASS as i64),
        ("ADAT_IN", WIRE_FEAT_ADAT_IN as i64),
        ("UPMIX", WIRE_FEAT_UPMIX as i64),
        ("UPMIX_PRESENCE", WIRE_FEAT_UPMIX_PRESENCE as i64),
        ("SPDIF_IN4", WIRE_FEAT_SPDIF_IN4 as i64),
        ("SUBHARM", WIRE_FEAT_SUBHARM as i64),
        ("SUBHARM_EXT", WIRE_FEAT_SUBHARM_EXT as i64),
        ("TUBE", WIRE_FEAT_TUBE as i64),
        ("LIMITER", WIRE_FEAT_LIMITER as i64),
        ("ALL", WIRE_FEATURES_ALL as i64),
    ] {
        assert_eq!(val(name), v, "{name}");
    }
}
